,"2285.8%","2420.3%","2554.8%","2689.3%","2823.8%","2958.3%","3092.8%","3227.3%","3361.8%","3496.3%"]},{"clave":"Multiplicador de Aturdimiento","valores":["133.1%","139.2%","145.3%","151.4%","157.5%","163.6%","169.7%","175.8%","181.9%","188%","194.1%","200.2%","206.3%","212.4%","218.5%","224.6%"]}]},{"categoria":"Habilidad fundamental","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2024/10/16/403606926/e6cb293ebaa906eb640d1f5926bae71c_8353080275965923878.png","tecnicas":[{"nombre":"Técnica pasiva: Percutor prepropulsado","descripcion":"Cuando Grace golpea a un enemigo con un ataque normal o un ataque rápido e inflige daño físico, obtiene 1 carga de calambre (pueden acumularse hasta 8 cargas). Cuando llega al límite de cargas de calambre, al ejecutar una técnica especial o una técnica especial EX, consumirá todas las cargas de calambre y aumentará la acumulación de anomalía eléctrica en un 65 / 75.8 / 86.6 / 97.5 / 108.3 / 119.1 / 130 %."},{"nombre":"Técnica adicional: Departamento de apoyo técnico","descripcion":"Si en el equipo hay miembros del mismo Atributo o la misma afiliación que ella:\nCuando Grace golpea a un enemigo al ejecutar una técnica especial EX, la próxima vez que el enemigo se vea afectado por electrochoque, el daño del efecto de electrochoque aumenta en un 18 %. Pueden acumularse hasta 2 cargas y activarse una vez en cada enemigo. Se reinicia al terminar el efecto de electrochoque."}],"atributos":[{"clave":"Técnica pasiva: Percutor prepropulsado","valores":["Nivel 1","Nivel 2 (A)","Nivel 3 (B)","Nivel 4 (C)","Nivel 5 (D)","Nivel 6 (E)","Nivel 7 (F)"]},{"clave":"Aumento de acumulación de anomalía eléctrica","valores":["65%","75.8%","86.6%","97.5%","108.3%","119.1%","130%"]},{"clave":"Tasa de Anomalía","valores":["-","+12 ptos.","-","+12 ptos.","-","+12 ptos.","-"]},{"clave":"Ataque Base","valores":["-","-","+25 ptos.","-","+25 ptos.","-","+25 ptos."]}]}],"materiales":[{"desde":1,"hasta":2,"creditos":0,"materiales":[{"nombre":"ディニー","ic