idad":3}]},{"desde":3,"hasta":4,"creditos":6000,"materiales":[{"nombre":"Chip físico avanzado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/9efabb10ff7561eb3bdd230e45b358de_5497698899113967867.png","cantidad":2}]},{"desde":4,"hasta":5,"creditos":9000,"materiales":[{"nombre":"Chip físico avanzado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/9efabb10ff7561eb3bdd230e45b358de_5497698899113967867.png","cantidad":3}]},{"desde":5,"hasta":6,"creditos":12000,"materiales":[{"nombre":"Chip físico avanzado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/9efabb10ff7561eb3bdd230e45b358de_5497698899113967867.png","cantidad":4}]},{"desde":6,"hasta":7,"creditos":18000,"materiales":[{"nombre":"Chip físico avanzado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/9efabb10ff7561eb3bdd230e45b358de_5497698899113967867.png","cantidad":6}]},{"desde":7,"hasta":8,"creditos":45000,"materiales":[{"nombre":"Chip físico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/886bb5b6c0b178366fc0183602ee1184_4925536009347499312.png","cantidad":5}]},{"desde":8,"hasta":9,"creditos":67500,"materiales":[{"nombre":"Chip físico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/886bb5b6c0b178366fc0183602ee1184_4925536009347499312.png","cantidad":8}]},{"desde":9,"hasta":10,"creditos":90000,"materiales":[{"nombre":"Chip físico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/886bb5b6c0b178366fc0183602ee1184_4925536009347499312.png","cantidad":10}]},{"desde":10,"hasta":11,"creditos":112500,"materiales":[{"nombre":"Chip físico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/886bb5b6c0b178366fc0183602ee1184_4925536009347499312.png","cantidad":12}]},{"desde":11,"hasta":12,"creditos":135000,"materiales":[{"nombre":"Chip físico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/886bb5b6c0b178366fc0183602ee1184_4925536009347499312.png","cantidad":15},{"nombre":"Descriptor «jaula de hámster»","icono":"","cantidad":1}]}]}'::jsonb, '[{"nivel":1,"nombre":"Entrada espectacular","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/6335146d351f78f0a628618f2a849181_3119698053713316104.png","efecto":"Al golpear a un enemigo con un ataque rápido o un contraataque, Billy recupera 2.7 ptos. adicionales de energía. Puede activarse una vez cada 5 s.","cita":"«¡Para ser maleantes, se portan muy bien! ¡Son como los agentes secundarios que acompañan al protagonista y que saltan para detener la bala!»"},{"nivel":2,"nombre":"Pistolero errante","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/469f9554aa138a057dacb98ede59a6d3_8037901845155267600.png","efecto":"Al ejecutar un contraataque, aumenta el daño infligido en un 25 %.\nLos disparos al rodar durante un ataque normal se consideran evasiones. Durante su ejecución, el agente se vuelve invulnerable y puede activar evasiones perfectas.\nAl activar una evasión perfecta por medio de un disparo al rodar, provoca de inmediato un contraataque.","cita":"«Los Caballeros Estelares nunca huyen del peligro. ¡Son lo que yo llamo \"pistoleros errantes\"!»\n—Usuario «MónicaDeMisSueños», en un foro de los Caballeros Estelares"},{"nivel":3,"nombre":"Enseñanzas del Caballero Estelar","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/28f2d7ccb68295e6b2c99fb99b577db4_8003165392045521961.png","efecto":"Nivel de ataque normal, evasión, técnica de apoyo, técnica especial y técnica en cadena +2","cita":"No reniegues de tu entrenamiento, ¡y no dejes de mejorar! Ese es el espíritu de los Caballeros Estelares, y Billy lo sigue al pie de la letra."},{"nivel":4,"nombre":"Bala justiciera estelar","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/fc5c9f6a7297408a0823e8ff2d31f79e_3427042453878724993.png","efecto":"Al golpear al enemigo con una técnica especial EX, aumenta la Probabilidad de Crítico en función de la distancia entre el agente y el objetivo. Cuanto más cerca esté Billy del objetivo, mayor es el efecto. Puede aumentar hasta en un 32 %.","cita":"Estas balas explosivas creadas por el propio Billy son extremadamente letales de cerca...\n... Aunque la intención original de Billy era simplemente inspirar asombro."},{"nivel":5,"nombre":"Tecnología perdida","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/ada22c7100cfcd504dc951c773bb06b8_8375432747173267291.png","efecto":"Nivel de ataque normal, evasión, técnica de apoyo, técnica especial y técnica en cadena +2","cita":"Unos componentes de precisión desconocidos y un diseño estructural único le conceden a Billy un rendimiento muy superior al de sus compañeros... Aunque también una factura elevada por mantenimiento."},{"nivel":6,"nombre":"Héroe estelar","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/cc8354becbb5422d928dcc39ba6df7fa_4143672430113157989.png","efecto":"Al golpear al enemigo 10 veces o al activar una evasión perfecta, aumenta el daño infligido de Billy en un 6 %. Pueden acumularse hasta 5 cargas. Este efecto se reinicia al recibir un golpe o ser arrojado por los aires.","cita":"«Uff, ¡me siento estupendo! A un lado, Anby, ¡es mi hora de brillar!»\n«Oye, Anby, ¿puedes poner el tema de los Caballeros Estelares?»\n—«10 frases estrictamente prohibidas en las Liebres Astutas», por Anby Demara"}]'::jsonb, null, null),
