691c7c57d51fdf1d545033591e1_4673394917071936894.png","cantidad":4}]},{"desde":6,"hasta":7,"creditos":18000,"materiales":[{"nombre":"Chip eléctrico avanzado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/33352691c7c57d51fdf1d545033591e1_4673394917071936894.png","cantidad":6}]},{"desde":7,"hasta":8,"creditos":45000,"materiales":[{"nombre":"Chip eléctrico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":5}]},{"desde":8,"hasta":9,"creditos":67500,"materiales":[{"nombre":"Chip eléctrico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":8}]},{"desde":9,"hasta":10,"creditos":90000,"materiales":[{"nombre":"Chip eléctrico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":10}]},{"desde":10,"hasta":11,"creditos":112500,"materiales":[{"nombre":"Chip eléctrico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":12}]},{"desde":11,"hasta":12,"creditos":135000,"materiales":[{"nombre":"Chip eléctrico especializado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eecba7ec05e22df475ff22f8aabe9f98_8024672642576344615.png","cantidad":15},{"nombre":"Descriptor «jaula de hámster»","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2024/08/08/403606926/c83fe1daf9847590cf19e6939fec8f2f_2767899454287074009.png","cantidad":1}]}]}'::jsonb, '[{"nivel":1,"nombre":"Modo supercargado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/6335146d351f78f0a628618f2a849181_3119698053713316104.png","efecto":"Al golpear a un enemigo con el cuarto corte del ataque normal, aumenta la Tasa de Energía de Anby en un 12 % durante 30 s.","cita":"«¡Con un minuto de recarga, puedes pelear hasta media hora!», eso le aseguró el vendedor de estos módulos expansivos de arma. Y ella lo comprobó al utilizarlos."},{"nivel":2,"nombre":"Descarga precisa","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/469f9554aa138a057dacb98ede59a6d3_8037901845155267600.png","efecto":"Al golpear a un enemigo afectado por Aturdimiento con ataque normal: Rayo descendente, aumenta el daño infligido en un 30 %. Al golpear a un enemigo que no esté afectado por Aturdimiento con la técnica especial EX, aumenta el Aturdimiento provocado en un 10 %.","cita":"«Unos cuantos toques te mandarán al país de los sueños». Mientras veía al enemigo caer ante ella, añadió: «Al menos, eso es lo que pasa en las películas»."},{"nivel":3,"nombre":"Buena disciplina","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/28f2d7ccb68295e6b2c99fb99b577db4_8003165392045521961.png","efecto":"Nivel de ataque normal, evasión, técnica especial y técnica en cadena +2","cita":"Corre y ataca como el rayo. Cuando de Cavidades se trata, es toda una experta."},{"nivel":4,"nombre":"Carga conductiva","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/fc5c9f6a7297408a0823e8ff2d31f79e_3427042453878724993.png","efecto":"Al usar la técnica en cadena o la técnica definitiva, los agentes inactivos eléctricos recuperan 3 ptos. de energía. Por cada 12 % de Tasa de Energía que tenga Anby, recuperarán 2 ptos. de energía adicionales. Pueden recuperar hasta 6 ptos. de esta forma.","cita":"Si prefieres pelear solo/a, no durarás mucho tiempo. Un saqueador de Cavidades experimentado sabe crear una ventana de oportunidad para sus compañeros."},{"nivel":5,"nombre":"Escuela de la vida","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/ada22c7100cfcd504dc951c773bb06b8_8375432747173267291.png","efecto":"Nivel de ataque normal, evasión, técnica especial y técnica en cadena +2","cita":"Trabajar para las Liebres Astutas no solo ayuda a fortalecer el espíritu, también ayuda (o más bien, te obliga) a mejorar tu condición física."},{"nivel":6,"nombre":"Campo de recarga","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/cc8354becbb5422d928dcc39ba6df7fa_4143672430113157989.png","efecto":"Al ejecutar una técnica especial EX, Anby obtiene 8 cargas energéticas (pueden acumularse hasta 8 cargas). Al golpear al enemigo con un ataque normal o un ataque rápido, consume 1 carga energética y aumenta el daño infligido en un 45 %.","cita":"Destellos eléctricos saltaban entre sus dedos. Al alzar la mirada, sus ojos rebosaban una ambición que iba más allá de su corta edad. Tal vez algún día se convierta en el ama de la electricidad."}]'::jsonb, null, null)
) as v(id, profile, skills, mindscapes, biography, source)
where c.id = v.id;

-- Comprobacion
select count(*) as agentes, count(skills) as con_habilidades, count(mindscapes) as con_cine_mental, count(biography_es) as con_biografia
from public.characters
where game_id = 'zenless-zone-zero';
